import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || join(root, 'data', 'workboard.sqlite');
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  archived INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
// Upgrade databases created before project archiving was introduced.
const projectColumns = db.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some(column => column.name === 'archived')) db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');

const send = (res, status, body, type = 'application/json; charset=utf-8') => {
  res.writeHead(status, { 'Content-Type': type, 'Cache-Control': 'no-store' });
  res.end(typeof body === 'string' ? body : JSON.stringify(body));
};
const readBody = (req) => new Promise((resolve, reject) => {
  let data = '';
  req.on('data', chunk => { data += chunk; if (data.length > 1e6) req.destroy(); });
  req.on('end', () => { try { resolve(JSON.parse(data || '{}')); } catch (e) { reject(e); } });
  req.on('error', reject);
});

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (url.pathname === '/health' && req.method === 'GET') return send(res, 200, { status: 'ok' });
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    return send(res, 200, db.prepare(`SELECT p.id, p.name, p.archived,
      COUNT(t.id) AS total_count, COALESCE(SUM(t.completed), 0) AS completed_count
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      GROUP BY p.id ORDER BY p.id ASC`).all().map(p => ({ ...p, archived: !!p.archived, summary: `${p.completed_count}/${p.total_count} completed` })));
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    try {
      const body = await readBody(req);
      const name = typeof body.name === 'string' ? body.name.trim() : '';
      if (!name) return send(res, 400, { error: 'Project name is required' });
      const result = db.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      return send(res, 201, { id: Number(result.lastInsertRowid), name });
    } catch { return send(res, 400, { error: 'Invalid request' }); }
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (archiveMatch && req.method === 'POST') {
    const changed = db.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(archiveMatch[2] === 'archive' ? 1 : 0, Number(archiveMatch[1]));
    return changed.changes ? send(res, 200, { ok: true }) : send(res, 404, { error: 'Project not found' });
  }
  const renameMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/rename$/);
  if (renameMatch && req.method === 'POST') {
    try {
      const body = await readBody(req);
      const name = typeof body.name === 'string' ? body.name.trim() : '';
      if (!name) return send(res, 400, { error: 'Project name is required' });
      const result = db.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0').run(name, Number(renameMatch[1]));
      return result.changes ? send(res, 200, { ok: true, name }) : send(res, 404, { error: 'Project not found or archived' });
    } catch { return send(res, 400, { error: 'Invalid request' }); }
  }
  const taskListMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (taskListMatch && req.method === 'GET') {
    return send(res, 200, db.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id ASC').all(Number(taskListMatch[1])).map(t => ({ ...t, completed: !!t.completed })));
  }
  if (taskListMatch && req.method === 'POST') {
    try {
      const projectId = Number(taskListMatch[1]);
      const owner = db.prepare('SELECT id, archived FROM projects WHERE id = ?').get(projectId);
      if (!owner) return send(res, 404, { error: 'Project not found' });
      if (owner.archived) return send(res, 403, { error: 'Archived projects cannot have tasks' });
      const body = await readBody(req);
      const title = typeof body.title === 'string' ? body.title.trim() : '';
      if (!title) return send(res, 400, { error: 'Task title is required' });
      const result = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
      return send(res, 201, { id: Number(result.lastInsertRowid), title, completed: false });
    } catch { return send(res, 400, { error: 'Invalid request' }); }
  }
  const taskRenameMatch = url.pathname.match(/^\/api\/tasks\/(\d+)\/rename$/);
  if (taskRenameMatch && req.method === 'POST') {
    try {
      const body = await readBody(req);
      const title = typeof body.title === 'string' ? body.title.trim() : '';
      if (!title) return send(res, 400, { error: 'Task title is required' });
      const result = db.prepare(`UPDATE tasks SET title = ? WHERE id = ? AND project_id IN
        (SELECT id FROM projects WHERE archived = 0)`).run(title, Number(taskRenameMatch[1]));
      return result.changes ? send(res, 200, { ok: true, title }) : send(res, 404, { error: 'Task not found or project archived' });
    } catch { return send(res, 400, { error: 'Invalid request' }); }
  }
  const taskMatch = url.pathname.match(/^\/api\/tasks\/(\d+)$/);
  if (taskMatch && req.method === 'PATCH') {
    try {
      const body = await readBody(req);
      if (typeof body.completed !== 'boolean') return send(res, 400, { error: 'Invalid completion state' });
      const result = db.prepare(`UPDATE tasks SET completed = ? WHERE id = ? AND project_id IN
        (SELECT id FROM projects WHERE archived = 0)`).run(body.completed ? 1 : 0, Number(taskMatch[1]));
      return result.changes ? send(res, 200, { ok: true }) : send(res, 404, { error: 'Task not found' });
    } catch { return send(res, 400, { error: 'Invalid request' }); }
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectMatch && req.method === 'GET') {
    const project = db.prepare('SELECT id, name, archived FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    return project ? send(res, 200, { ...project, archived: !!project.archived }) : send(res, 404, { error: 'Project not found' });
  }
  if (url.pathname.startsWith('/api/')) return send(res, 404, { error: 'Not found' });
  if (req.method === 'GET') {
    const requested = url.pathname === '/' ? 'index.html' : url.pathname.replace(/^\/+/, '');
    const path = ['app.js', 'style.css'].includes(requested) ? requested : 'index.html';
    try {
      const { readFileSync } = await import('node:fs');
      const content = readFileSync(join(root, 'public', path));
      const type = path.endsWith('.js') ? 'text/javascript; charset=utf-8' : path.endsWith('.css') ? 'text/css; charset=utf-8' : 'text/html; charset=utf-8';
      res.writeHead(200, { 'Content-Type': type }); return res.end(content);
    } catch { return send(res, 404, 'Not found', 'text/plain; charset=utf-8'); }
  }
  send(res, 404, 'Not found', 'text/plain; charset=utf-8');
});
server.listen(Number(process.env.PORT || 8080), '0.0.0.0');

const app = document.querySelector('#app');

function element(tag, text, className) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  if (className) node.className = className;
  return node;
}

async function render() {
  app.replaceChildren();
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (match) {
    let project;
    try {
      const response = await fetch(`/api/projects/${match[1]}`);
      if (!response.ok) throw new Error('Project not found');
      project = await response.json();
    } catch {
      app.append(element('h1', 'Project not found'));
      const back = element('button', 'Projects');
      back.addEventListener('click', () => navigate('/'));
      app.append(back);
      return;
    }
    app.append(element('h1', project.name));
    if (project.archived) app.append(element('p', 'Archived project')); 
    const back = element('button', 'Projects');
    back.addEventListener('click', () => navigate('/'));
    app.append(back);

    const renameForm = element('form', undefined, 'create-form');
    const renameLabel = element('label', 'New project name');
    renameLabel.htmlFor = 'new-project-name';
    const renameInput = element('input');
    renameInput.id = 'new-project-name';
    renameInput.type = 'text';
    renameInput.autocomplete = 'off';
    renameInput.value = project.name;
    renameInput.disabled = project.archived;
    const renameButton = element('button', 'Rename project');
    renameButton.type = 'submit';
    renameButton.disabled = project.archived;
    renameForm.append(renameLabel, renameInput, renameButton);
    const renameAlert = element('p', '', 'alert');
    renameAlert.setAttribute('role', 'alert');
    renameAlert.hidden = true;
    app.append(renameForm, renameAlert);
    renameForm.addEventListener('submit', async event => {
      event.preventDefault();
      const name = renameInput.value.trim();
      if (!name) {
        renameAlert.textContent = 'Project name is required';
        renameAlert.hidden = false;
        renameInput.focus();
        return;
      }
      const response = await fetch(`/api/projects/${match[1]}/rename`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
      });
      if (!response.ok) {
        renameAlert.textContent = 'Project name is required';
        renameAlert.hidden = false;
        return;
      }
      renameAlert.hidden = true;
      renameInput.value = name;
      app.querySelector('h1').textContent = name;
    });

    const form = element('form', undefined, 'create-form');
    const label = element('label', 'Task title');
    label.htmlFor = 'task-title';
    const input = element('input');
    input.id = 'task-title';
    input.type = 'text';
    input.autocomplete = 'off';
    const submit = element('button', 'Create task');
    submit.type = 'submit';
    if (project.archived) submit.disabled = true;
    form.append(label, input, submit);
    const alert = element('p', '', 'alert');
    alert.setAttribute('role', 'alert');
    alert.hidden = true;
    const filterLabel = element('label', 'Task filter');
    filterLabel.htmlFor = 'task-filter';
    const filter = element('select');
    filter.id = 'task-filter';
    for (const value of ['All', 'Open', 'Completed']) filter.append(new Option(value, value));
    const list = element('section', undefined, 'task-list');
    app.append(form, alert, filterLabel, filter, list);

    async function loadTasks() {
      const response = await fetch(`/api/projects/${match[1]}/tasks`);
      const tasks = await response.json();
      list.replaceChildren();
      for (const task of tasks.filter(t => filter.value === 'All' || (filter.value === 'Completed') === t.completed)) {
        const row = element('div', undefined, 'task-row');
        row.dataset.testid = 'task-row';
        row.append(element('span', task.title));
        const checkbox = element('input');
        checkbox.type = 'checkbox';
        checkbox.checked = task.completed;
        checkbox.disabled = project.archived;
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        checkbox.addEventListener('change', async () => {
          await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
          await loadTasks();
        });
        row.append(checkbox);
        const renameForm = element('form', undefined, 'create-form');
        const renameInput = element('input');
        renameInput.type = 'text';
        renameInput.value = task.title;
        renameInput.setAttribute('aria-label', 'New task title');
        renameInput.disabled = project.archived;
        const renameButton = element('button', 'Rename task');
        renameButton.type = 'submit';
        renameButton.disabled = project.archived;
        renameForm.append(renameInput, renameButton);
        const renameAlert = element('p', '', 'alert');
        renameAlert.setAttribute('role', 'alert');
        renameAlert.hidden = true;
        renameForm.addEventListener('submit', async event => {
          event.preventDefault();
          const title = renameInput.value.trim();
          if (!title) {
            renameAlert.textContent = 'Task title is required';
            renameAlert.hidden = false;
            renameInput.focus();
            return;
          }
          const response = await fetch(`/api/tasks/${task.id}/rename`, {
            method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title })
          });
          if (!response.ok) {
            renameAlert.textContent = 'Task title is required';
            renameAlert.hidden = false;
            return;
          }
          await loadTasks();
        });
        row.append(renameForm, renameAlert);
        list.append(row);
      }
    }
    filter.addEventListener('change', loadTasks);
    form.addEventListener('submit', async event => {
      event.preventDefault();
      const title = input.value.trim();
      if (!title) { alert.textContent = 'Task title is required'; alert.hidden = false; input.focus(); return; }
      const response = await fetch(`/api/projects/${match[1]}/tasks`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title }) });
      if (!response.ok) { alert.textContent = 'Task title is required'; alert.hidden = false; return; }
      alert.hidden = true;
      input.value = '';
      await loadTasks();
    });
    await loadTasks();
    return;
  }

  app.append(element('h1', 'Workboard'));
  const form = element('form', undefined, 'create-form');
  const label = element('label', 'Project name');
  label.htmlFor = 'project-name';
  const input = element('input');
  input.id = 'project-name';
  input.name = 'name';
  input.type = 'text';
  input.autocomplete = 'off';
  const submit = element('button', 'Create project');
  submit.type = 'submit';
  form.append(label, input, submit);
  const alert = element('p', '', 'alert');
  alert.setAttribute('role', 'alert');
  alert.hidden = true;
  const filterLabel = element('label', 'Project filter');
  filterLabel.htmlFor = 'project-filter';
  const filter = element('select');
  filter.id = 'project-filter';
  for (const value of ['Active', 'Archived']) filter.append(new Option(value, value));
  const list = element('section', undefined, 'project-list');
  list.setAttribute('aria-label', 'Projects');
  app.append(form, alert, filterLabel, filter, list);

  async function loadProjects() {
    const response = await fetch('/api/projects');
    const projects = await response.json();
    list.replaceChildren();
    for (const project of projects.filter(p => p.archived === (filter.value === 'Archived'))) {
      const row = element('div', undefined, 'project-row');
      row.dataset.testid = 'project-row';
      const details = element('div');
      details.append(element('span', project.name));
      const summary = element('span', project.summary, 'project-summary');
      summary.dataset.testid = 'project-summary';
      details.append(summary);
      row.append(details);
      const open = element('button', 'Open project');
      open.type = 'button';
      open.addEventListener('click', () => navigate(`/projects/${project.id}`));
      row.append(open);
      const action = element('button', project.archived ? 'Restore project' : 'Archive project');
      action.type = 'button';
      action.addEventListener('click', async () => {
        await fetch(`/api/projects/${project.id}/${project.archived ? 'restore' : 'archive'}`, { method: 'POST' });
        await loadProjects();
      });
      row.append(action);
      list.append(row);
    }
  }
  filter.addEventListener('change', loadProjects);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      input.focus();
      return;
    }
    const response = await fetch('/api/projects', {
      method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name })
    });
    if (!response.ok) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      return;
    }
    alert.hidden = true;
    input.value = '';
    await loadProjects();
  });
  await loadProjects();
}

function navigate(path) {
  history.pushState({}, '', path);
  render();
}
window.addEventListener('popstate', render);
render();
